// Frontend/src/hooks/useMessages.js
import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:5000/api';

const useMessages = () => {
  const [conversations, setConversations] = useState([]);
  const [messages, setMessages] = useState([]);
  const [currentConversation, setCurrentConversation] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Fonction pour récupérer le token
  const getToken = () => {
    const token = localStorage.getItem('authToken'); // Correction: 'authToken' au lieu de 'token'
    if (!token || token === 'undefined' || token === 'null') {
      console.error('Token non trouvé dans localStorage');
      return null;
    }
    return token;
  };

  // Configuration axios avec intercepteurs
  const axiosInstance = axios.create({
    baseURL: API_URL,
    timeout: 10000,
  });

  // Interceptor pour ajouter le token
  axiosInstance.interceptors.request.use(
    (config) => {
      const token = getToken();
      if (token) {
        config.headers.Authorization = `Bearer ${token}`;
      }
      return config;
    },
    (error) => {
      return Promise.reject(error);
    }
  );

  // Interceptor pour gérer les erreurs
  axiosInstance.interceptors.response.use(
    (response) => response,
    (error) => {
      if (error.response?.status === 401) {
        setError('Session expirée. Veuillez vous reconnecter.');
        localStorage.removeItem('authToken');
        localStorage.removeItem('userData');
        window.location.href = '/login';
      }
      return Promise.reject(error);
    }
  );

  // Récupérer toutes les conversations
  const fetchConversations = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await axiosInstance.get('/messages/conversations');

      if (response.data.success) {
        setConversations(response.data.conversations || []);
      } else {
        setError(response.data.message || 'Erreur lors du chargement des conversations');
      }
    } catch (err) {
      console.error('Erreur fetchConversations:', err);

      if (err.response?.status === 401) {
        setError('Veuillez vous reconnecter');
      } else if (err.code === 'ECONNABORTED') {
        setError('Délai de connexion dépassé');
      } else if (!err.response) {
        setError('Serveur non disponible');
      } else {
        setError(err.response.data?.message || 'Erreur de connexion');
      }
    } finally {
      setLoading(false);
    }
  }, [axiosInstance]);

  // Récupérer ou créer une conversation
  const getOrCreateConversation = useCallback(async (adminId) => {
    try {
      setLoading(true);
      setError(null);

      const response = await axiosInstance.post('/messages/conversations/create', {
        admin_id: adminId
      });

      if (response.data.success) {
        const conversation = response.data.conversation;
        setCurrentConversation(conversation);
        return conversation;
      } else {
        setError(response.data.message || 'Erreur lors de la création de la conversation');
      }
    } catch (err) {
      console.error('Erreur getOrCreateConversation:', err);
      setError(err.response?.data?.message || 'Erreur de connexion');
    } finally {
      setLoading(false);
    }
  }, [axiosInstance]);

  // Récupérer les messages d'une conversation
  const fetchMessages = useCallback(async (conversationId) => {
    try {
      setLoading(true);
      setError(null);

      const response = await axiosInstance.get(`/messages/conversations/${conversationId}/messages`);

      if (response.data.success) {
        setMessages(response.data.messages || []);
        setCurrentConversation(response.data.conversation);
      } else {
        setError(response.data.message || 'Erreur lors du chargement des messages');
      }
    } catch (err) {
      console.error('Erreur fetchMessages:', err);

      if (err.response?.status === 404) {
        setError('Conversation non trouvée');
      } else {
        setError(err.response?.data?.message || 'Erreur de connexion');
      }
    } finally {
      setLoading(false);
    }
  }, [axiosInstance]);

  // Envoyer un message
  const sendMessage = useCallback(async (conversationId, content) => {
    try {
      const response = await axiosInstance.post(
        `/messages/conversations/${conversationId}/messages`,
        { content }
      );

      if (response.data.success) {
        const newMessage = response.data.message;
        setMessages(prev => [...prev, newMessage]);
        return newMessage;
      } else {
        setError(response.data.message || 'Erreur lors de l\'envoi du message');
        throw new Error(response.data.message);
      }
    } catch (err) {
      console.error('Erreur sendMessage:', err);
      setError(err.response?.data?.message || 'Erreur lors de l\'envoi du message');
      throw err;
    }
  }, [axiosInstance]);

  // Récupérer les admins disponibles
  const fetchAdmins = useCallback(async () => {
    try {
      const response = await axiosInstance.get('/users/admins');

      if (response.data.success) {
        return response.data.admins;
      } else {
        setError(response.data.message || 'Erreur lors du chargement des admins');
        return [];
      }
    } catch (err) {
      console.error('Erreur fetchAdmins:', err);
      setError('Erreur lors du chargement des admins');
      return [];
    }
  }, [axiosInstance]);

  // Initialiser les conversations au montage
  useEffect(() => {
    const token = getToken();
    if (token) {
      fetchConversations();
    } else {
      setError('Vous devez vous connecter pour accéder aux messages');
    }
  }, [fetchConversations]);

  return {
    conversations,
    messages,
    currentConversation,
    loading,
    error,
    fetchConversations,
    getOrCreateConversation,
    fetchMessages,
    sendMessage,
    fetchAdmins,
    setError,
    setMessages
  };
};

export default useMessages;
